function cleanPhone(raw) {
  var p = String(raw || '').replace(/[^0-9]/g, '');
  if (p === '') { return ''; }
  if (p.length === 11 && p.charAt(0) === '0') { return '91' + p.substring(1); }
  if (p.length === 10 && '6789'.indexOf(p.charAt(0)) !== -1) { return '91' + p; }
  if (p.length === 12 && p.substring(0, 2) === '91') { return p; }
  if (p.length >= 11 && p.length <= 15) { return p; }
  return '91' + p;
}

// Read the webhook by name: 'Get Order Context' sits between the webhook and
// this node, so $input holds the context lookup, not the customer's payload.
var hook = $('PWA Webhook').first().json;
var d = hook.body || hook;

var ctx = $input.first().json || {};
if (Array.isArray(ctx)) { ctx = ctx[0] || {}; }
var cust = ctx.customer || ctx || {};
var repeat = Number(cust.total_orders || 0) > 0;

var items = Array.isArray(d.items) ? d.items : [];

var phone = cleanPhone(d.customer_phone || d.phone);
if (phone === '' || items.length === 0) {
  return [{ json: { invalid: true,
    reason: phone === '' ? 'Missing or invalid phone number' : 'Cart is empty' } }];
}

var itemsStr = items.map(function (i) {
  var n = i.name || i.item_name || '';
  var q = Number(i.quantity) || 1;
  return n + ' x' + q + (i.notes ? ' (' + i.notes + ')' : '');
}).join(', ');

var total = Number(d.total);
if (!total) {
  total = items.reduce(function (s, i) {
    return s + ((Number(i.price) || 0) * (Number(i.quantity) || 1));
  }, 0);
}

var type = d.order_type || 'delivery';
if (['delivery','takeaway','dine-in'].indexOf(type) === -1) { type = 'delivery'; }

// --- dine-in ---
var table = String(d.table_number || '').trim();
var session = String(d.session_id || '').trim();
if (table !== '' && type !== 'dine-in') { type = 'dine-in'; }
if (type === 'dine-in' && table === '') { type = 'takeaway'; }
if (!/^[0-9a-fA-F-]{36}$/.test(session)) { session = ''; }
var payMode = (type === 'delivery') ? 'cod' : 'cash_counter';

// --- staff discount: only trusted once Verify Staff (Discount) confirms a
// real staff session - a spoofed 'source: pos' or a missing token just gets
// silently zeroed, never a broken/failed order. Unlike loyalty redemption,
// the amount is already fully known here, so it reduces `total` directly
// rather than needing a later PATCH. ---
var requestedDiscount = Math.max(0, Number(d.discount_amount) || 0);
var discountReason = String(d.discount_reason || '').trim();
var staffOk = false;
try {
  var vs = $('Verify Staff (Discount)').first().json;
  staffOk = !!(vs && vs.statusCode === 200 && vs.body && vs.body.staff === true);
} catch (e) { staffOk = false; }
var discountAmount = (requestedDiscount > 0 && staffOk) ? Math.min(requestedDiscount, total) : 0;
if (discountAmount > 0) { total = total - discountAmount; }

// --- delivery fee: computed here from `settings`, never trusted from the
// client (same discipline as the discount above). Free above a configured
// order value; takeaway/dine-in never pay it. Folded straight into `total`
// before the order is inserted, same as the discount - no separate column. ---
var settingsRows = [];
try {
  var gs = $('Get Settings').first().json;
  settingsRows = (gs && gs.body) ? gs.body : [];
} catch (e) { settingsRows = []; }
var settingsMap = {};
settingsRows.forEach(function (r) { settingsMap[r.key] = r.value; });
var deliveryFeeCfg = Number(settingsMap.delivery_fee || 0);
var freeDeliveryAbove = Number(settingsMap.free_delivery_above || 500);
var deliveryFee = (type === 'delivery' && deliveryFeeCfg > 0 && total < freeDeliveryAbove) ? deliveryFeeCfg : 0;
if (deliveryFee > 0) { total = total + deliveryFee; }

// --- loyalty redemption: this is just the customer's request, passed
// through. The real cap (balance + max-redeem-per-order) is enforced
// atomically inside the redeem_loyalty_points RPC later in this chain,
// not duplicated here. ---
var requestedRedeemPoints = Math.max(0, Number(d.redeem_points) || 0);

// --- online payment: only for delivery/takeaway - dine-in is always pay-at-
// counter per CLAUDE.md's business model, so a dine-in request for online
// payment is silently treated as cash rather than erroring. Cash stays the
// default for everything else too - this is additive, not a replacement. ---
var wantsOnline = String(d.payment_method || '').toLowerCase() === 'razorpay';
var paymentMethod = (wantsOnline && type !== 'dine-in') ? 'razorpay' : 'cash';
var paymentStatus = paymentMethod === 'razorpay' ? 'pending' : 'n/a';

// --- counter orders ---
var isPos = String(d.source || '').toLowerCase() === 'pos';
var staff = String(d.staff || '').trim();
var nowIso = new Date().toISOString();

return [{ json: {
  invalid: false,
  customer_phone: phone,
  customer_name: d.customer_name || d.name || cust.name || '',
  items: itemsStr,
  raw_items: items,
  total: total,
  requested_redeem_points: requestedRedeemPoints,
  discount_amount: discountAmount,
  discount_reason: discountReason,
  delivery_fee: deliveryFee,
  payment_method: paymentMethod,
  payment_status: paymentStatus,
  order_type: type,
  address: type === 'dine-in' ? '' : (d.address || ''),
  landmark: d.landmark || '',
  city: d.city || 'Mangaluru',
  pincode: d.pincode || '',
  table_number: table,
  session_id: session,
  payment_mode: payMode,
  is_repeat_customer: repeat,
  source: isPos ? 'pos' : 'pwa',
  status: isPos ? 'preparing' : 'new',
  accepted_at: isPos ? nowIso : null,
  accepted_by: isPos ? (staff || 'Counter') : null,
  taken_by: isPos ? (staff || 'Counter') : null
} }];

var phone = '', content = '', message_id = '', order_number = '';
try {
  var b = $('Build Receipt Image Message').first().json;
  phone = b.phone; order_number = b.order_number || '';
  if (b.outgoing && b.outgoing.type === 'text') {
    content = '[tab update] ' + ((b.outgoing.text && b.outgoing.text.body) || '');
  } else if (b.via_template) {
    content = '[order confirmed template] ' + order_number;
  } else {
    content = '[receipt image] ' + ((b.outgoing && b.outgoing.image && b.outgoing.image.caption) || '');
  }
} catch (e) {}
try {
  var si = $('Send Invoice Image').first().json;
  if (si && si.id && si.id) message_id = si.id;
} catch (e) {}
return [{ json: { phone: phone, content: content, message_id: message_id, order_number: order_number } }];

var created = $('Insert Order').first().json;
var rows = created.body !== undefined ? created.body : created;
var order = Array.isArray(rows) ? (rows[0] || {}) : (rows || {});
var d = $('Prepare Order').first().json;
var orderNumber = order.order_number || '';

var es = $('Ensure Session').first().json;
var esBody = (es && es.body) ? es.body : es;
var roundNo = Number((esBody && esBody.round_no) || 1);
var isDineInExtraRound = (d.order_type === 'dine-in' && roundNo > 1);

var recentRows = [];
try {
  var chk = $('Check Recent Inbound').first().json;
  var body = (chk && chk.body !== undefined) ? chk.body : chk;
  recentRows = Array.isArray(body) ? body : (body ? [body] : []);
} catch (e) { recentRows = []; }
var hasRecentInbound = recentRows.some(function (r) { return r && r.id; });

if (isDineInExtraRound) {
  // CLAUDE.md: dine-in gets one confirmation at round 1, then nothing until
  // the invoice at close - status pings per round are noise. The one
  // deliberate exception is this short 'added to your tab' nudge, so a
  // round placed from the counter doesn't look like it vanished. It can
  // only go out as free-form text (no approved template exists for this
  // shape yet), so outside the 24h inbound window it's skipped entirely -
  // true silence, same as the original spec - rather than erroring.
  if (!hasRecentInbound) { return []; }
  var tabTotal = 0;
  try {
    // Get Tab Orders is a GET against a JSON-array endpoint, so n8n splits
    // the response into one item per row - .first() would silently drop
    // every row but the first and undercount the running tab.
    var gtItems = $('Get Tab Orders').all();
    tabTotal = gtItems.reduce(function (s, it) {
      var j = it.json; var row = (j && j.body !== undefined) ? j.body : j;
      return s + (Number(row && row.total) || 0);
    }, 0);
  } catch (e) { tabTotal = 0; }
  if (!tabTotal) { tabTotal = Number(order.total != null ? order.total : d.total) || 0; }
  var content = 'Added to Table ' + (d.table_number || '') + ': ' + (d.items || 'your order') +
    '. Tab so far: ₹' + tabTotal.toFixed(2);
  return [{ json: { phone: d.customer_phone, order_number: orderNumber, via_template: false,
    outgoing: { type: 'text', text: { body: content } } } }];
}

var imgUrl = 'https://staff.brightmedia.tech/webhook/friedking-receipt?order_number=' + encodeURIComponent(orderNumber) + '&key=fk_bWzKMd0MI4U3WEUCAGYlQxcb';

var outgoing;
if (hasRecentInbound) {
  outgoing = { type: 'image', image: { link: imgUrl, caption: 'Thanks! Your order ' + orderNumber + ' is confirmed.' } };
} else {
  outgoing = { type: 'template', template: { name: 'friedking_order_confirmed', language: { code: 'en' },
    components: [
      { type: 'header', parameters: [ { type: 'image', image: { link: imgUrl } } ] },
      { type: 'body', parameters: [
          { type: 'text', text: (d.customer_name || 'Guest') },
          { type: 'text', text: orderNumber },
          { type: 'text', text: String(order.total != null ? order.total : d.total) }
      ] }
    ] } };
}

return [{ json: { phone: d.customer_phone, order_number: orderNumber, via_template: !hasRecentInbound, outgoing: outgoing } }];
